<?php
declare(strict_types=1);
namespace DigiForge\Tests;
use PHPUnit\Framework\TestCase;
use DigiForge\IndependentAcceptance\{Authority,Protocol};
final class PrintifyIndependentAuthorityTest extends TestCase {
 private \IndependentAuthorityFixture $f;
 protected function setUp():void {self::assertFileExists(__DIR__.'/../../contracts/printify-authority/Authority.php','Offline independent dispatcher contract required');require_once __DIR__.'/../../contracts/printify-authority/Authority.php';require_once __DIR__.'/../fixtures/IndependentAuthorityFixture.php';$this->f=new \IndependentAuthorityFixture();}
 public function testValidSignedGetIsMinimizedAndAudited():void {$r=$this->f->a->dispatch($this->f->request());self::assertSame('OBSERVED',$r['receipt']['status']);self::assertTrue($r['receipt_committed']);self::assertSame(1,$this->f->provider->calls);self::assertStringNotContainsString('buyer-private',json_encode($r));self::assertSame(3,count($this->f->store->s['audit']));self::assertTrue(sodium_crypto_sign_verify_detached(base64_decode($r['signature']),Protocol::canonical($r['receipt']),$this->f->config['receipt_public_key']));}
 public function testUnsignedOrTamperedAuthorityDenied():void {$r=$this->f->request();$r['manifest']['slot']=1;self::assertSame('DENIED',$this->f->a->dispatch($r)['status']);$r=$this->f->request();$r['signature']='invalid';self::assertSame('DENIED',$this->f->a->dispatch($r)['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testExpiredFutureAndOverlongOwnerAuthorityDenied():void {foreach([['expires_at'=>999],['issued_at'=>1001],['expires_at'=>1301],['owner_verified_at'=>300]] as $bad)self::assertSame('DENIED',$this->f->a->dispatch($this->f->request($bad))['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testWrongActorShopAccountAndIntegrationDeniedEvenWithValidSignature():void {foreach(['actor'=>2,'shop_key'=>'standard_pod','internal_shop_id'=>3,'integration_id'=>4,'provider_shop_id'=>'28925875','account'=>'other-account','credential_binding'=>str_repeat('0',64),'epoch'=>str_repeat('0',64)] as $k=>$v)self::assertSame('DENIED',$this->f->a->dispatch($this->f->request([$k=>$v]))['status'],$k);self::assertSame(0,$this->f->provider->calls);}
 public function testMutationsAndArbitraryProxyInputsDenied():void {foreach(['POST','PUT','PATCH','DELETE','HEAD'] as $method)self::assertSame('DENIED',$this->f->a->dispatch($this->f->request(['request'=>['operation'=>'SHOPS_READ','method'=>$method,'endpoint'=>'/v1/shops.json','body'=>[]]]))['status']);foreach(['/v1/shops/28925875/products.json?page=1&limit=1','https://evil.invalid/x','/v1/uploads/images.json'] as $path)self::assertSame('DENIED',$this->f->a->dispatch($this->f->request(['request'=>['operation'=>'SHOPS_READ','method'=>'GET','endpoint'=>$path,'body'=>[]]]))['status']);$r=$this->f->request();$r['url']='https://evil.invalid';self::assertSame('DENIED',$this->f->a->dispatch($r)['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testDuplicateNonceAndSlotNeverDispatchTwice():void {$m=$this->f->request();$this->f->a->dispatch($m);self::assertSame('DENIED',$this->f->a->dispatch($m)['status']);self::assertSame('DENIED',$this->f->a->dispatch($this->f->request(['nonce'=>str_repeat('b',32)]))['status']);self::assertSame(1,$this->f->provider->calls);}
 public function testHostingerDatabaseFilesystemCoordinatedAndApplicationRollbackCannotRewindExternalAuthority():void {$old=$this->f->request();$this->f->a->emergency($this->f->stop());foreach(['database','filesystem','both','application'] as $kind){$host=['generation'=>1,'enabled'=>true,'old_application_checks'=>false,'restored'=>$kind];self::assertSame('DENIED',$this->f->legacyCaller($old,$host)['status']);}self::assertSame(0,$this->f->provider->calls);self::assertSame(2,$this->f->store->s['generation']);}
 public function testAuthorityOutageNeverReachesProvider():void {$this->f->store->available=false;self::assertSame('DENIED',$this->f->a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);self::assertFalse($this->f->a->emergency($this->f->stop())['durable_revocation_recorded']);}
 public function testCredentialUnavailableNeverReachesProvider():void {$this->f->provider->credentialAvailable=false;self::assertSame('DENIED',$this->f->a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testProviderTimeoutIsUnknownConsumedAndNotRetried():void {$this->f->provider->failure=true;$request=$this->f->request();$r=$this->f->a->dispatch($request);self::assertSame('UNKNOWN',$r['receipt']['status']);self::assertStringNotContainsString('sensitive-exception',json_encode($r));self::assertSame('DENIED',$this->f->a->dispatch($request)['status']);self::assertSame(1,$this->f->provider->calls);}
 public function testEmergencyBeforeFinalAdmissionPreventsPhysicalSend():void {$this->f->store->before=function($n){if($n===2){$this->f->store->before=null;$r=$this->f->a->emergency($this->f->stop());self::assertSame('DRAIN_ACKNOWLEDGED',$r['receipt']['status']);}};self::assertSame('DENIED',$this->f->a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testEmergencyDuringAdmittedGetIsPendingAndResponseUnknown():void {$stop=null;$this->f->provider->during=function()use(&$stop){$stop=$this->f->a->emergency($this->f->stop());};$r=$this->f->a->dispatch($this->f->request());self::assertSame('DRAIN_PENDING',$stop['receipt']['status']);self::assertSame('UNKNOWN',$r['receipt']['status']);self::assertSame(['values_disclosed'=>false],$r['receipt']['observations']);self::assertSame('DENIED',$this->f->a->dispatch($this->f->request(['slot'=>1]))['status']);$ack=$this->f->a->emergency($this->f->stop(['nonce'=>str_repeat('c',32)]));self::assertSame('DRAIN_ACKNOWLEDGED',$ack['receipt']['status']);}
 public function testPostDispatchStoreOutageCannotProduceAcceptedReceiptOrDrainAck():void {$this->f->provider->during=function(){$this->f->store->available=false;};$r=$this->f->a->dispatch($this->f->request());self::assertSame('UNKNOWN',$r['status']);self::assertFalse($r['receipt_committed']);$this->f->store->available=true;$stop=$this->f->a->emergency($this->f->stop());self::assertSame('DRAIN_PENDING',$stop['receipt']['status']);}
 public function testRequestCommitAcknowledgementLossNeverSendsOrReplays():void {$request=$this->f->request();$this->f->store->loseCommitAck=true;self::assertSame('DENIED',$this->f->a->dispatch($request)['status']);self::assertSame('DENIED',$this->f->a->dispatch($request)['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testAccountRateBudgetSharedAcrossSlots():void {for($i=0;$i<3;$i++)self::assertSame('OBSERVED',$this->f->a->dispatch($this->f->request(['slot'=>$i,'nonce'=>str_pad((string)$i,32,'0')]))['receipt']['status']);self::assertSame('DENIED',$this->f->a->dispatch($this->f->request(['slot'=>3,'nonce'=>str_repeat('d',32)]))['status']);self::assertSame(3,$this->f->provider->calls);}
 public function testProviderRetryAfterDeniesNewReadWithoutRetry():void {$this->f->provider->response=['status'=>429,'body'=>'{}','retry_after'=>120];$r=$this->f->a->dispatch($this->f->request());self::assertSame('REJECTED',$r['receipt']['status']);self::assertSame('DENIED',$this->f->a->dispatch($this->f->request(['slot'=>1]))['status']);self::assertSame(1,$this->f->provider->calls);}
 public function testMalformedOversizedAndRedirectResponsesAreNeverAccepted():void {foreach([['status'=>200,'body'=>'{'],['status'=>200,'body'=>str_repeat('x',1048577)],['status'=>302,'body'=>'{}']] as $i=>$response){$this->f->provider->response=$response;$r=$this->f->a->dispatch($this->f->request(['slot'=>$i,'nonce'=>str_pad((string)$i,32,'0')]));self::assertNotSame('OBSERVED',$r['receipt']['status']);}self::assertSame(3,$this->f->provider->calls);}
 public function testStopSignatureDomainAndReplayProtection():void {$get=$this->f->request();self::assertFalse($this->f->a->emergency($get)['durable_revocation_recorded']);$stop=$this->f->stop();self::assertSame('DRAIN_ACKNOWLEDGED',$this->f->a->emergency($stop)['receipt']['status']);self::assertFalse($this->f->a->emergency($stop)['durable_revocation_recorded']);}
 public function testAuthorityRestoreRequiresNewIndependentEpoch():void {$this->f->store->s['epoch']=str_repeat('0',64);self::assertSame('DENIED',$this->f->a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testMissingIndependentCustodyQualificationKeepsServiceDisabled():void {$cfg=$this->f->config;$cfg['exclusive_credential_custody']=false;$a=$this->f->authority($cfg);self::assertSame('DENIED',$a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testReceiptSignerFailurePreventsDispatch():void {$this->f->signer->available=false;self::assertSame('DENIED',$this->f->a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testCatalogGrantCannotBeInventedBySignedCaller():void {$r=$this->f->request(['request'=>['operation'=>'BLUEPRINTS','method'=>'GET','endpoint'=>'/v1/catalog/blueprints.json','body'=>[]]]);self::assertSame('DENIED',$this->f->a->dispatch($r)['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testMalformedPersistedClaimsCannotAcknowledgeDrain():void {foreach([['state'=>'CORRUPT'],['state'=>null],[]] as $claim){$f=new \IndependentAuthorityFixture();$f->store->s['claims']['uncertain']=$claim;self::assertFalse($f->a->emergency($f->stop())['durable_revocation_recorded']);self::assertSame('DENIED',$f->a->dispatch($f->request())['status']);self::assertSame(0,$f->provider->calls);}}
 public function testMalformedQuotaEvidenceCannotRestoreBudget():void {$this->f->store->s['times']=['bad',1000];self::assertSame('DENIED',$this->f->a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testAuditTamperingDeniesFurtherDispatchAndAcknowledgement():void {$this->f->a->dispatch($this->f->request());$this->f->store->s['audit'][0]['receipt']['event']='ALTERED';self::assertSame('DENIED',$this->f->a->dispatch($this->f->request(['slot'=>1]))['status']);self::assertFalse($this->f->a->emergency($this->f->stop())['durable_revocation_recorded']);self::assertSame(1,$this->f->provider->calls);}
 public function testRevokedSessionCannotSend():void {$this->f->store->s['sessions'][str_repeat('a',32)]['revoked']=true;self::assertSame('DENIED',$this->f->a->dispatch($this->f->request())['status']);self::assertSame(0,$this->f->provider->calls);}
 public function testCatalogGrantCheckedAfterApprovedSlotAndCannotExpandScope():void {
  $request=['operation'=>'BLUEPRINTS','method'=>'GET','endpoint'=>'/v1/catalog/blueprints.json','body'=>[]];$session=str_repeat('a',32);$id=str_repeat('9',64);$hash=hash('sha256',Protocol::canonical($request));
  $this->f->store->s['sessions'][$session]['slots'][0]=$hash;
  $envelope=$this->f->request(['request'=>$request,'catalog_grant'=>$id]);self::assertSame('DENIED',$this->f->a->dispatch($envelope)['status']);
  $grant=['revoked'=>false,'expires_at'=>1300,'session'=>$session,'generation'=>1,'account'=>$this->f->config['account'],'credential_binding'=>$this->f->config['credential_binding'],'provider_shop_id'=>'28930593','slots'=>[0=>$hash]];
  foreach([['revoked'=>true],['expires_at'=>999],['expires_at'=>'never'],['expires_at'=>1300.0],['expires_at'=>true],['account'=>'other'],['provider_shop_id'=>'28925875'],['generation'=>2],['slots'=>[1=>$hash]]] as $bad){$this->f->store->s['catalog_grants'][$id]=array_replace($grant,$bad);self::assertSame('DENIED',$this->f->a->dispatch($envelope)['status']);}
  self::assertSame(0,$this->f->provider->calls);$this->f->store->s['catalog_grants'][$id]=$grant;self::assertSame('OBSERVED',$this->f->a->dispatch($envelope)['receipt']['status']);self::assertSame(1,$this->f->provider->calls);self::assertSame('DENIED',$this->f->a->dispatch($envelope)['status']);
 }
 public function testDispatchServiceOutageIsUnknownAndNeverRetried():void {$this->f->provider->failure=true;$r=$this->f->request();self::assertSame('UNKNOWN',$this->f->a->dispatch($r)['receipt']['status']);self::assertSame('DENIED',$this->f->a->dispatch($r)['status']);self::assertSame(1,$this->f->provider->calls);}
 public function testCanonicalProtocolRejectsFloatsObjectsAndDeepInputs():void {foreach([1.2,new \stdClass()] as $v){try{Protocol::canonical($v);self::fail('Unbounded type accepted');}catch(\RuntimeException){self::assertTrue(true);}}}

 public function testMalformedSessionExpiryDenied():void {foreach(['never',1300.0,true,null,[],1301] as $expiry){$f=new \IndependentAuthorityFixture();$f->store->s['sessions'][str_repeat('a',32)]['expires_at']=$expiry;self::assertSame('DENIED',$f->a->dispatch($f->request())['status']);self::assertSame(0,$f->provider->calls);}}

}
